const uuid=(name)=>{const h=crypto.createHash('sha1').update(group+':'+name).digest();h[6]=(h[6]&15)|80;h[8]=(h[8]&63)|128;const x=h.subarray(0,16).toString('hex');return `${x.slice(0,8)}-${x.slice(8,12)}-${x.slice(12,16)}-${x.slice(16,20)}-${x.slice(20)}`}
const nutrition={calories:251,protein_g:4.4,carbs_g:30.9,fat_g:12.6,saturated_fat_g:7.8,fiber_g:3.5,sugar_g:3.3,sodium_mg:561,estimated:true,source:'USDA FoodData Central — SR Legacy (abril de 2018)',source_url:'https://fdc.nal.usda.gov/',serving_size:'1 porción (1/6 de la receta)',method:'Suma por 100 g aplicada a 1000 g de papa cruda con piel retirada (FDC 170026 como aproximación), 250 g de leche entera (FDC 171265), 80 g de mantequilla sin sal (FDC 173430) y 8 g de sal (FDC 173468), dividida entre 6. La pimienta y el agua no se contabilizan.',note:'Estimación por formulación, no análisis de laboratorio. El rendimiento, la variedad y el agua absorbida cambian el peso final; la sal añadida concentra la mayor incertidumbre del sodio.'}
const packs={
es:{slug,title:'Puré de papa cremoso',excerpt:'Puré de papa suave y cremoso con mantequilla y leche caliente, sin grumos ni textura gomosa.',summary:'Este puré de papa cremoso usa papa harinosa, mantequilla y leche entera. Cocer desde agua fría, escurrir bien, prensar en caliente e incorporar los lácteos tibios da una guarnición lisa y ligera.',category:'Guarniciones',course:'Guarnición',cuisine:'Internacional',difficulty:'Fácil',group:'Para el puré',ingredients:['papa harinosa, pelada|1000|g','leche entera|250|ml','mantequilla sin sal, más 10 g opcionales para servir|80|g','sal fina total|8|g','pimienta negra molida|1|g'],steps:[['Corta las papas','Corta las papas peladas en trozos uniformes de unos 3 cm. Así se cuecen al mismo ritmo.'],['Cubre con agua fría','Pon los trozos en una olla, cúbrelos con agua fría unos 2 cm por encima y añade 6 g de sal.'],['Cuece suavemente','Lleva a ebullición y cocina a hervor suave de 15 a 18 minutos, hasta que un cuchillo atraviese el centro sin resistencia.'],['Escurre por completo','Vierte las papas en un colador y déjalas escurrir 2 minutos para que el vapor elimine humedad superficial.'],['Calienta los lácteos','Calienta la leche con 80 g de mantequilla a fuego bajo hasta que se derrita, sin dejar que hierva.'],['Prensa las papas','Pasa las papas todavía calientes por un prensapapas o pasapurés dentro de una olla limpia. No uses batidora ni procesador.'],['Incorpora la leche','Añade la mezcla tibia poco a poco y dóblala con espátula hasta obtener un puré liso. Ajusta con los 2 g de sal restantes y la pimienta.'],['Sirve caliente','Pasa el puré a una fuente, forma ondas con una cuchara y sirve de inmediato; añade la mantequilla opcional solo al presentar.']],notes:'Usa una papa harinosa, como russet, para un puré ligero; una papa amarilla da un resultado más denso y mantecoso. No batas ni proceses: el exceso de trabajo libera almidón y vuelve el puré pegajoso. Añade los lácteos calientes gradualmente. Contiene leche. Puedes usar leche sin lactosa y mantequilla sin lactosa; las bebidas vegetales cambian sabor y textura. Mantén caliente a 60 °C o más si no sirves de inmediato. Refrigera antes de 2 horas, en recipiente tapado, hasta 3 días; recalienta a 74 °C con un poco de leche. No congela bien.',seoTitle:'Puré de papa cremoso: receta fácil y sin grumos | Manual de Cocina',seoDesc:'Cómo hacer puré de papa cremoso con mantequilla y leche caliente. Cantidades exactas, 8 pasos y trucos para evitar una textura gomosa.',keywords:['puré de papa cremoso','puré de papas','guarnición de papa','puré sin grumos'],faqs:[['¿Qué papa es mejor para un puré cremoso?','Una papa harinosa, como russet, se deshace con facilidad y queda ligera. Las papas amarillas dan un puré más denso y mantecoso.'],['¿Por qué el puré queda gomoso?','Porque la papa se trabaja demasiado y libera almidón. Usa prensapapas o pasapurés y mezcla con espátula; evita licuadora, procesador y batidora eléctrica.'],['¿La leche debe estar caliente?','Sí, tibia o caliente pero sin hervir. Se incorpora mejor y evita enfriar de golpe la papa recién prensada.'],['¿Se puede preparar con antelación?','Sí. Refrigera tapado hasta 3 días y recalienta lentamente con un chorrito de leche, hasta alcanzar 74 °C.'],['¿Cómo hacer puré sin lactosa?','Sustituye por leche y mantequilla sin lactosa en las mismas cantidades. Una bebida vegetal también funciona, pero modifica el sabor y puede dejarlo menos cremoso.']]},
en:{slug:'creamy-mashed-potatoes',title:'Creamy mashed potatoes: smooth, buttery and lump-free',excerpt:'Smooth creamy mashed potatoes with warm milk and butter, without lumps or a gluey texture.',summary:'These creamy mashed potatoes use floury potatoes, butter and whole milk. Starting in cold water, draining thoroughly, ricing while hot and folding in warm dairy keeps the texture smooth and light.',category:'Side dishes',course:'Side dish',cuisine:'International',difficulty:'Easy',group:'For the mash',ingredients:['floury potatoes, peeled|1000|g','whole milk|250|ml','unsalted butter, plus 10 g optional for serving|80|g','fine salt, total|8|g','ground black pepper|1|g'],steps:[['Cut the potatoes','Cut the peeled potatoes into even 3 cm chunks so they cook at the same rate.'],['Cover with cold water','Place them in a saucepan, cover with cold water by about 2 cm and add 6 g salt.'],['Simmer gently','Bring to the boil and simmer gently for 15–18 minutes, until a knife slides through the centre without resistance.'],['Drain thoroughly','Tip the potatoes into a colander and leave for 2 minutes so steam removes surface moisture.'],['Warm the dairy','Heat the milk with 80 g butter over low heat until melted, without boiling.'],['Rice the potatoes','Pass the still-hot potatoes through a ricer or food mill into a clean saucepan. Do not use a blender or processor.'],['Fold in the milk','Add the warm mixture gradually and fold with a spatula until smooth. Season with the remaining 2 g salt and pepper.'],['Serve hot','Spoon into a serving bowl, make soft swirls and serve immediately; add the optional butter only at the table.']],notes:'Use floury potatoes such as russets for a light mash; yellow potatoes make it denser and more buttery. Do not whip or process: overworking releases starch and makes mash gluey. Add the warm dairy gradually. Contains milk. Lactose-free milk and butter can be used; plant drinks change flavour and texture. Hold at 60 °C or above if not serving immediately. Refrigerate within 2 hours for up to 3 days and reheat to 74 °C with a little milk. Freezing is not recommended.',seoTitle:'Creamy mashed potatoes: smooth and lump-free | Manual de Cocina',seoDesc:'How to make creamy mashed potatoes with warm milk and butter. Exact quantities, 8 clear steps and tips to prevent gluey mash.',keywords:['creamy mashed potatoes','smooth mashed potatoes','potato side dish','lump-free mash'],faqs:[['Which potatoes are best for creamy mash?','Floury potatoes such as russets break down easily and stay light. Yellow potatoes make a denser, more buttery mash.'],['Why do mashed potatoes turn gluey?','Overworking releases too much starch. Use a ricer or food mill and fold with a spatula; avoid blenders, processors and electric beaters.'],['Should the milk be hot?','Yes—warm or hot but not boiling. It folds in more easily and does not chill the freshly riced potatoes.'],['Can mashed potatoes be made ahead?','Yes. Refrigerate covered for up to 3 days and reheat gently with a splash of milk until 74 °C.'],['How can I make them lactose-free?','Use lactose-free milk and butter in the same quantities. Plant drinks also work, but change the flavour and may be less creamy.']]},
de:{slug:'cremiges-kartoffelpueree',title:'Cremiges Kartoffelpüree: glatt, buttrig und ohne Klümpchen',excerpt:'Glattes Kartoffelpüree mit warmer Milch und Butter, ohne Klümpchen oder klebrige Konsistenz.',summary:'Für dieses cremige Kartoffelpüree werden mehligkochende Kartoffeln, Butter und Vollmilch verwendet. In kaltem Wasser ansetzen, gut abtropfen, heiß durchpressen und warme Milch unterheben.',category:'Beilagen',course:'Beilage',cuisine:'International',difficulty:'Einfach',group:'Für das Püree',ingredients:['mehligkochende Kartoffeln, geschält|1000|g','Vollmilch|250|ml','ungesalzene Butter, plus optional 10 g zum Servieren|80|g','feines Salz, gesamt|8|g','gemahlener schwarzer Pfeffer|1|g'],steps:[['Kartoffeln schneiden','Die geschälten Kartoffeln in gleichmäßige, etwa 3 cm große Stücke schneiden.'],['Kalt aufsetzen','In einen Topf geben, etwa 2 cm mit kaltem Wasser bedecken und 6 g Salz zugeben.'],['Sanft garen','Aufkochen und 15–18 Minuten leise köcheln, bis ein Messer ohne Widerstand in die Mitte gleitet.'],['Gründlich abgießen','In ein Sieb gießen und 2 Minuten ausdampfen lassen, damit Oberflächenfeuchte entweicht.'],['Milch und Butter erwärmen','Milch und 80 g Butter bei niedriger Hitze erwärmen, bis die Butter schmilzt; nicht kochen.'],['Kartoffeln durchpressen','Die noch heißen Kartoffeln durch eine Kartoffelpresse oder Flotte Lotte in einen sauberen Topf drücken.'],['Milch unterheben','Die warme Mischung nach und nach mit einem Spatel unterheben. Mit restlichen 2 g Salz und Pfeffer abschmecken.'],['Heiß servieren','In eine Schüssel füllen, Wellen ziehen und sofort servieren; optionale Butter erst beim Anrichten zugeben.']],notes:'Mehligkochende Kartoffeln ergeben ein leichtes Püree; gelbfleischige Sorten werden dichter und buttriger. Nicht mixen: zu viel Bearbeitung setzt Stärke frei und macht das Püree klebrig. Enthält Milch. Laktosefreie Milch und Butter funktionieren; Pflanzendrinks verändern Geschmack und Textur. Warm bei mindestens 60 °C halten. Innerhalb von 2 Stunden kühlen, bis zu 3 Tage lagern und mit etwas Milch auf 74 °C erhitzen. Nicht ideal zum Einfrieren.',seoTitle:'Cremiges Kartoffelpüree ohne Klümpchen | Manual de Cocina',seoDesc:'Cremiges Kartoffelpüree mit warmer Milch und Butter: genaue Mengen, 8 Schritte und Tipps gegen klebrige Konsistenz.',keywords:['cremiges Kartoffelpüree','Kartoffelpüree ohne Klümpchen','Kartoffelbeilage'],faqs:[['Welche Kartoffeln eignen sich am besten?','Mehligkochende Sorten wie Russet zerfallen leicht und ergeben ein lockeres Püree. Gelbfleischige Sorten werden dichter.'],['Warum wird Kartoffelpüree klebrig?','Zu starkes Bearbeiten setzt Stärke frei. Kartoffelpresse oder Flotte Lotte verwenden und nur vorsichtig unterheben.'],['Muss die Milch warm sein?','Ja, warm aber nicht kochend. So verbindet sie sich leichter und kühlt die heißen Kartoffeln nicht ab.'],['Kann man es vorbereiten?','Ja. Abgedeckt bis zu 3 Tage kühlen und mit etwas Milch langsam auf 74 °C erwärmen.'],['Wie gelingt es laktosefrei?','Laktosefreie Milch und Butter im gleichen Verhältnis verwenden. Pflanzendrinks verändern Geschmack und Cremigkeit.']]},
fr:{slug:'puree-de-pommes-de-terre-cremeuse',title:'Purée de pommes de terre crémeuse, lisse et sans grumeaux',excerpt:'Purée de pommes de terre lisse avec lait chaud et beurre, sans grumeaux ni texture collante.',summary:'Cette purée crémeuse associe pommes de terre farineuses, beurre et lait entier. Un départ à froid, un égouttage soigné, le presse-purée et les laitages chauds donnent une texture légère.',category:'Accompagnements',course:'Accompagnement',cuisine:'Internationale',difficulty:'Facile',group:'Pour la purée',ingredients:['pommes de terre farineuses, épluchées|1000|g','lait entier|250|ml','beurre doux, plus 10 g facultatifs pour servir|80|g','sel fin, total|8|g','poivre noir moulu|1|g'],steps:[['Couper les pommes de terre','Couper les pommes de terre épluchées en morceaux réguliers de 3 cm.'],['Couvrir d’eau froide','Les mettre dans une casserole, couvrir d’eau froide sur 2 cm et ajouter 6 g de sel.'],['Cuire doucement','Porter à ébullition puis frémir 15 à 18 minutes, jusqu’à ce qu’un couteau traverse le centre sans résistance.'],['Bien égoutter','Verser dans une passoire et laisser évaporer 2 minutes pour retirer l’humidité de surface.'],['Chauffer les laitages','Chauffer le lait avec 80 g de beurre à feu doux jusqu’à fonte, sans faire bouillir.'],['Passer les pommes de terre','Passer les pommes de terre encore chaudes au presse-purée ou au moulin dans une casserole propre.'],['Incorporer le lait','Ajouter progressivement le mélange chaud et incorporer à la spatule. Assaisonner avec les 2 g de sel restants et le poivre.'],['Servir chaud','Transférer dans un plat, former des vagues et servir aussitôt; ajouter le beurre facultatif au dressage.']],notes:'Choisir des pommes de terre farineuses pour une purée légère; les variétés jaunes donnent un résultat plus dense. Ne pas mixer: l’excès de travail libère l’amidon et rend la purée collante. Contient du lait. Le lait et le beurre sans lactose conviennent; les boissons végétales modifient le goût. Maintenir à 60 °C minimum. Réfrigérer sous 2 heures, conserver 3 jours et réchauffer à 74 °C avec un peu de lait. La congélation est déconseillée.',seoTitle:'Purée de pommes de terre crémeuse et lisse | Manual de Cocina',seoDesc:'Purée crémeuse au lait chaud et au beurre: quantités exactes, 8 étapes et conseils pour éviter une texture collante.',keywords:['purée de pommes de terre crémeuse','purée sans grumeaux','accompagnement pommes de terre'],faqs:[['Quelles pommes de terre choisir?','Les variétés farineuses se défont facilement et donnent une purée légère. Les pommes de terre jaunes donnent une texture plus dense.'],['Pourquoi la purée devient-elle collante?','Un travail excessif libère trop d’amidon. Utilisez un presse-purée ou un moulin et incorporez doucement.'],['Le lait doit-il être chaud?','Oui, chaud mais non bouillant. Il s’incorpore mieux sans refroidir les pommes de terre.'],['Peut-on la préparer à l’avance?','Oui. Conservez-la couverte 3 jours et réchauffez doucement avec un peu de lait jusqu’à 74 °C.'],['Comment la faire sans lactose?','Utilisez lait et beurre sans lactose aux mêmes quantités. Une boisson végétale modifie le goût et la texture.']]},
it:{slug:'pure-di-patate-cremoso',title:'Purè di patate cremoso, liscio e senza grumi',excerpt:'Purè liscio con latte caldo e burro, senza grumi né consistenza collosa.',summary:'Questo purè cremoso usa patate farinose, burro e latte intero. Partire da acqua fredda, scolare bene, schiacciare da calde e incorporare i latticini tiepidi.',category:'Contorni',course:'Contorno',cuisine:'Internazionale',difficulty:'Facile',group:'Per il purè',ingredients:['patate farinose, sbucciate|1000|g','latte intero|250|ml','burro non salato, più 10 g facoltativi per servire|80|g','sale fino totale|8|g','pepe nero macinato|1|g'],steps:[['Taglia le patate','Taglia le patate sbucciate in pezzi uniformi di circa 3 cm.'],['Copri con acqua fredda','Mettile in pentola, copri con 2 cm di acqua fredda e aggiungi 6 g di sale.'],['Cuoci dolcemente','Porta a bollore e sobbolle 15–18 minuti, finché un coltello attraversa il centro senza resistenza.'],['Scola bene','Versa nello scolapasta e lascia evaporare 2 minuti per eliminare l’umidità superficiale.'],['Scalda latte e burro','Scalda il latte con 80 g di burro a fuoco basso finché si scioglie, senza bollire.'],['Schiaccia le patate','Passa le patate ancora calde nello schiacciapatate o passaverdure dentro una pentola pulita.'],['Incorpora il latte','Aggiungi gradualmente il composto caldo e incorpora con una spatola. Regola con i 2 g di sale rimasti e pepe.'],['Servi caldo','Trasferisci in una ciotola, forma onde e servi subito; aggiungi il burro facoltativo solo al momento.']],notes:'Usa patate farinose per un purè leggero; quelle gialle danno una consistenza più densa e burrosa. Non frullare: il lavoro eccessivo libera amido e rende il purè colloso. Contiene latte. Latte e burro senza lattosio funzionano; le bevande vegetali cambiano sapore e consistenza. Mantieni ad almeno 60 °C. Raffredda entro 2 ore, conserva 3 giorni e riscalda a 74 °C con poco latte. Sconsigliato congelare.',seoTitle:'Purè di patate cremoso e senza grumi | Manual de Cocina',seoDesc:'Purè cremoso con latte caldo e burro: dosi esatte, 8 passaggi e consigli per evitare una consistenza collosa.',keywords:['purè di patate cremoso','purè senza grumi','contorno di patate'],faqs:[['Quali patate sono migliori?','Le patate farinose si sfaldano facilmente e danno un purè leggero. Quelle gialle lo rendono più denso.'],['Perché il purè diventa colloso?','Lavorarlo troppo libera amido. Usa schiacciapatate o passaverdure e incorpora delicatamente.'],['Il latte deve essere caldo?','Sì, caldo ma non bollente. Si incorpora meglio e non raffredda le patate.'],['Si può preparare in anticipo?','Sì. Conserva coperto 3 giorni e riscalda con poco latte fino a 74 °C.'],['Come farlo senza lattosio?','Usa latte e burro senza lattosio nelle stesse quantità. Le bevande vegetali cambiano gusto e cremosità.']]},
ja:{slug:'クリーミーマッシュポテト',title:'クリーミーマッシュポテト｜なめらかでダマにならない作り方',excerpt:'温めた牛乳とバターで作る、ダマや粘りのないなめらかなマッシュポテト。',summary:'粉質のじゃがいも、無塩バター、全乳で作る基本のマッシュポテトです。冷水からゆで、よく水を切り、熱いうちにつぶして温かい乳製品を混ぜます。',category:'付け合わせ',course:'付け合わせ',cuisine:'各国料理',difficulty:'簡単',group:'マッシュポテト',ingredients:['粉質じゃがいも（皮をむく）|1000|g','全乳|250|ml','無塩バター（仕上げ用10 gは任意）|80|g','細塩（合計）|8|g','黒こしょう|1|g'],steps:[['じゃがいもを切る','皮をむいたじゃがいもを約3 cmの均一な大きさに切ります。'],['冷水に入れる','鍋に入れ、上2 cmまで冷水を注ぎ、塩6 gを加えます。'],['弱くゆでる','沸騰後は弱い煮立ちで15〜18分、ナイフが中心まで抵抗なく入るまで加熱します。'],['しっかり水を切る','ざるにあけ、表面の水分が蒸発するよう2分置きます。'],['牛乳とバターを温める','牛乳とバター80 gを弱火で温め、沸騰させずに溶かします。'],['じゃがいもを押しつぶす','熱いうちにポテトライサーかフードミルで清潔な鍋に押し出します。ミキサーは使いません。'],['牛乳を混ぜる','温かい液を少しずつ加え、へらでやさしく混ぜます。残りの塩2 gとこしょうで調えます。'],['温かいうちに盛る','器に盛ってスプーンで波形を作り、すぐに提供します。任意のバターは盛り付け時に加えます。']],notes:'軽い食感には粉質のじゃがいも、濃厚さには黄肉種が向きます。ミキサーで練るとでんぷんが出て粘るため避けます。乳成分を含みます。乳糖不使用の牛乳とバターに同量で置換できますが、植物性飲料は風味と食感が変わります。すぐ出さない場合は60℃以上を保ちます。2時間以内に冷蔵し3日以内、少量の牛乳を加えて74℃まで再加熱します。冷凍は不向きです。',seoTitle:'クリーミーマッシュポテトの作り方 | Manual de Cocina',seoDesc:'温かい牛乳とバターで作るなめらかなマッシュポテト。正確な分量、8工程、粘りを防ぐコツを紹介。',keywords:['マッシュポテト','クリーミーマッシュポテト','じゃがいもの付け合わせ'],faqs:[['どのじゃがいもが向いていますか？','粉質の品種は崩れやすく軽い仕上がりです。黄肉種はより濃厚で密な食感になります。'],['なぜ粘りが出ますか？','混ぜすぎるとでんぷんが出るためです。ライサーかフードミルを使い、へらでやさしく混ぜます。'],['牛乳は温めますか？','はい。沸騰させず温めると混ざりやすく、熱いじゃがいもを冷ましません。'],['作り置きできますか？','密閉して冷蔵3日まで。牛乳少量を加え、74℃までゆっくり再加熱します。'],['乳糖不使用にできますか？','乳糖不使用の牛乳とバターを同量使えます。植物性飲料は味とクリーミーさが変わります。']]},
pt:{slug:'pure-de-batata-cremoso',title:'Purê de batata cremoso, liso e sem grumos',excerpt:'Purê liso com leite quente e manteiga, sem grumos nem textura pegajosa.',summary:'Este purê cremoso usa batata farinhenta, manteiga e leite integral. Começar em água fria, escorrer bem, passar ainda quente e incorporar os laticínios mornos.',category:'Acompanhamentos',course:'Acompanhamento',cuisine:'Internacional',difficulty:'Fácil',group:'Para o purê',ingredients:['batata farinhenta, descascada|1000|g','leite integral|250|ml','manteiga sem sal, mais 10 g opcionais para servir|80|g','sal fino total|8|g','pimenta-do-reino moída|1|g'],steps:[['Corte as batatas','Corte as batatas descascadas em pedaços uniformes de cerca de 3 cm.'],['Cubra com água fria','Coloque na panela, cubra com 2 cm de água fria e adicione 6 g de sal.'],['Cozinhe suavemente','Ferva e cozinhe em fogo brando por 15–18 minutos, até a faca atravessar o centro sem resistência.'],['Escorra bem','Passe para um escorredor e deixe 2 minutos para o vapor eliminar a umidade superficial.'],['Aqueça os laticínios','Aqueça o leite com 80 g de manteiga em fogo baixo até derreter, sem ferver.'],['Passe as batatas','Passe as batatas ainda quentes no espremedor ou passe-vite para uma panela limpa.'],['Incorpore o leite','Junte a mistura morna aos poucos e envolva com espátula. Tempere com os 2 g de sal restantes e pimenta.'],['Sirva quente','Transfira para uma travessa, faça ondas e sirva imediatamente; adicione a manteiga opcional só ao finalizar.']],notes:'Use batata farinhenta para um purê leve; variedades amarelas ficam mais densas e amanteigadas. Não bata nem processe: o excesso de trabalho libera amido e deixa o purê pegajoso. Contém leite. Leite e manteiga sem lactose funcionam; bebidas vegetais mudam sabor e textura. Mantenha a 60 °C ou mais. Refrigere em até 2 horas por até 3 dias e reaqueça a 74 °C com um pouco de leite. Não congela bem.',seoTitle:'Purê de batata cremoso e sem grumos | Manual de Cocina',seoDesc:'Purê cremoso com leite quente e manteiga: quantidades exatas, 8 etapas e dicas para evitar textura pegajosa.',keywords:['purê de batata cremoso','purê sem grumos','acompanhamento de batata'],faqs:[['Qual batata é melhor?','A batata farinhenta se desfaz facilmente e fica leve. As amarelas produzem um purê mais denso e amanteigado.'],['Por que o purê fica pegajoso?','Trabalhar demais libera amido. Use espremedor ou passe-vite e envolva suavemente.'],['O leite deve estar quente?','Sim, quente mas sem ferver. Ele se incorpora melhor e não esfria as batatas.'],['Posso preparar antes?','Sim. Guarde tampado por 3 dias e reaqueça com um pouco de leite até 74 °C.'],['Como fazer sem lactose?','Use leite e manteiga sem lactose nas mesmas quantidades. Bebidas vegetais alteram sabor e cremosidade.']]}
}
