const sql=`-- Run only AFTER ${mediaDir} is deployed and all 12 WebP return HTTP 200 with exact hashes.\nDO $pure$\nDECLARE\n j constant jsonb := $records$${json}$records$::jsonb;\n g constant uuid := '${group}';\n n int;\nBEGIN\n IF NOT EXISTS (SELECT 1 FROM recipes WHERE id='${esId}' AND recipe_group_id=g AND language='es' AND slug='${slug}' AND public_path='/pure-de-papa-cremoso' AND published=false AND editorial_status='archived' AND created_at='2026-09-25 00:03:11.941373+00') THEN RAISE EXCEPTION 'Expected archived ES identity state diverged'; END IF;\n IF NOT EXISTS (SELECT 1 FROM content_redirects WHERE id='5a77b77c-f570-42d2-8598-d0a13928ff6e' AND source_path='/pure-de-papa-cremoso' AND target_path='/es/recetas' AND status_code=302) THEN RAISE EXCEPTION 'Expected temporary 302 diverged'; END IF;\n IF EXISTS (SELECT 1 FROM recipes WHERE recipe_group_id<>g AND (public_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(j) x) OR (language,slug) IN (SELECT x->>'language',x->>'slug' FROM jsonb_array_elements(j) x))) THEN RAISE EXCEPTION 'Recipe route collision'; END IF;\n IF EXISTS (SELECT 1 FROM content_pages WHERE public_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(j) x)) THEN RAISE EXCEPTION 'Content page collision'; END IF;\n UPDATE recipes r SET title=x.title,excerpt=x.excerpt,ingredients=x.ingredients,steps=x.steps,category=x.category,prep_time_minutes=x.prep_time_minutes,cook_time_minutes=x.cook_time_minutes,servings=x.servings,image_url=x.image_url,published=x.published,published_at=x.published_at,updated_at=now(),content_html=x.content_html,summary=x.summary,notes=x.notes,difficulty=x.difficulty,course=x.course,cuisine=x.cuisine,total_time_minutes=x.total_time_minutes,keywords=x.keywords,nutrition=x.nutrition,gallery=x.gallery,video_urls=x.video_urls,seo=x.seo,public_path=x.public_path,editorial_status=x.editorial_status,ready_at=x.ready_at,rating_count=0,rating_sum=0 FROM jsonb_to_recordset(j) x(id uuid,language text,slug text,title text,excerpt text,ingredients jsonb,steps jsonb,category text,prep_time_minutes int,cook_time_minutes int,servings int,image_url text,published boolean,published_at timestamptz,content_html text,summary text,notes text,difficulty text,course text,cuisine text,total_time_minutes int,keywords jsonb,nutrition jsonb,gallery jsonb,video_urls jsonb,seo jsonb,public_path text,editorial_status text,ready_at timestamptz) WHERE r.id='${esId}' AND x.language='es' AND x.id=r.id;\n INSERT INTO recipes (id,recipe_group_id,language,slug,title,excerpt,ingredients,steps,category,prep_time_minutes,cook_time_minutes,servings,image_url,published,published_at,content_html,summary,notes,difficulty,course,cuisine,total_time_minutes,keywords,nutrition,gallery,video_urls,seo,source_post_id,source_url,public_path,editorial_status,ready_at,rating_count,rating_sum) SELECT x.id,g,x.language,x.slug,x.title,x.excerpt,x.ingredients,x.steps,x.category,x.prep_time_minutes,x.cook_time_minutes,x.servings,x.image_url,x.published,x.published_at,x.content_html,x.summary,x.notes,x.difficulty,x.course,x.cuisine,x.total_time_minutes,x.keywords,x.nutrition,x.gallery,x.video_urls,x.seo,NULL,NULL,x.public_path,x.editorial_status,x.ready_at,0,0 FROM jsonb_to_recordset(j) x(id uuid,language text,slug text,title text,excerpt text,ingredients jsonb,steps jsonb,category text,prep_time_minutes int,cook_time_minutes int,servings int,image_url text,published boolean,published_at timestamptz,content_html text,summary text,notes text,difficulty text,course text,cuisine text,total_time_minutes int,keywords jsonb,nutrition jsonb,gallery jsonb,video_urls jsonb,seo jsonb,public_path text,editorial_status text,ready_at timestamptz) WHERE x.language<>'es' ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,excerpt=EXCLUDED.excerpt,ingredients=EXCLUDED.ingredients,steps=EXCLUDED.steps,category=EXCLUDED.category,prep_time_minutes=EXCLUDED.prep_time_minutes,cook_time_minutes=EXCLUDED.cook_time_minutes,servings=EXCLUDED.servings,image_url=EXCLUDED.image_url,published=EXCLUDED.published,published_at=EXCLUDED.published_at,updated_at=now(),content_html=EXCLUDED.content_html,summary=EXCLUDED.summary,notes=EXCLUDED.notes,difficulty=EXCLUDED.difficulty,course=EXCLUDED.course,cuisine=EXCLUDED.cuisine,total_time_minutes=EXCLUDED.total_time_minutes,keywords=EXCLUDED.keywords,nutrition=EXCLUDED.nutrition,gallery=EXCLUDED.gallery,video_urls=EXCLUDED.video_urls,seo=EXCLUDED.seo,public_path=EXCLUDED.public_path,editorial_status=EXCLUDED.editorial_status,ready_at=EXCLUDED.ready_at;\n DELETE FROM content_redirects WHERE id='5a77b77c-f570-42d2-8598-d0a13928ff6e' AND source_path='/pure-de-papa-cremoso' AND target_path='/es/recetas' AND status_code=302;\n SELECT count(*) INTO n FROM recipes WHERE recipe_group_id=g AND published=true AND editorial_status='published';\n IF n<>7 THEN RAISE EXCEPTION 'Expected 7/7 published rows, got %',n; END IF;\nEND $pure$;\n`
